class PeakMemClustering:
    def peakmem_clarans(self, n_samples: int) -> None:
        CLARANS(
            n_clusters=4,
            num_local=2,
            random_state=42,
        ).fit(self.X)

    def setup(self, n_samples: int) -> None:
        rng = np.random.RandomState(42)
        self.X = rng.randn(n_samples, 10)

