class TimeInitialization:
    def time_initialization(self, init_method: str) -> None:
        FastCLARANS(
            n_clusters=4,
            init=init_method,
            num_local=1,
            random_state=42,
        ).fit(self.X)

    def setup(self, init_method: str) -> None:
        rng = np.random.RandomState(42)
        self.X = rng.randn(400, 8)
